with lines as (select c.id, c.created_at, c.coupon_codes, item.qty, item.price, item.promo from carts c lateral view outer explode(c.items) x as item), cleaned as (select *, round(price / qty, 2) as price_per_qty, coalesce(promo, 'NONE') as resolved_promo from lines where created_at > date '2025-03-02' and created_at >= '2024-05-23'), remaining_keys as (select id from cleaned except distinct select id from carts where customer_id is not null), kept_rows as (select s.* from cleaned s join remaining_keys k on s.id = k.id), enriched as (select qty, promo, price_per_qty, resolved_promo, avg(price_per_qty) over w_ordered as price_per_qty_avg_30m, max(qty) over w_ordered as qty_max_30m, stddev_samp(qty) over (partition by to_date(created_at), promo) as created_at_to_date_stddev_samp_qty, min(price_per_qty) over (partition by year(created_at)) as created_at_year_min_price_per_qty, percent_rank() over w_grp as price_per_qty_percent_rank from kept_rows window w_ordered as (partition by promo order by cast(created_at as bigint) range between 1800 preceding and current row), w_grp as (partition by promo order by price_per_qty nulls last)), valid as (select qty, promo, price_per_qty, resolved_promo, price_per_qty_avg_30m, qty_max_30m, created_at_to_date_stddev_samp_qty, price_per_qty_percent_rank, coalesce(promo, 'Unknown') as promo_filled from enriched where created_at_to_date_stddev_samp_qty >= 2), enriched_carts as (select *, percent_rank() over (partition by promo order by qty desc) as qty_percent_rank from valid), with_windows as (select *, percent_rank() over w_hist as qty_max_30m_percent_rank, stddev_samp(qty) over (partition by promo) as promo_stddev_samp_qty from enriched_carts window w_hist as (partition by promo order by qty_max_30m desc nulls first)) select promo, count(*) filter (where promo = 'VIP') as vip_rows, size(collect_set(promo)) as num_promos, count(case when promo = 'WELCOME5' then 1 end) as welcome5_count, count(*) as event_count from with_windows group by promo order by num_promos desc;
